&reftitle.description;
public SoapServer::__construct stringnullwsdl arrayoptions[]
Метод инициализирует объект SoapServer для работы в режиме WSDL или без WSDL-спецификации.

  &reftitle.examples;



    Пример инициализации объекта SoapServer методом SoapServer::__construct


<?php

$server = new SoapServer("some.wsdl");

$server = new SoapServer("some.wsdl", array('soap_version' => SOAP_1_2));

$server = new SoapServer("some.wsdl", array('actor' => "http://example.org/ts-tests/C"));

$server = new SoapServer("some.wsdl", array('encoding' => 'ISO-8859-1'));

$server = new SoapServer(null, array('uri' => "http://test-uri/"));

class MyBook
{
    public $title;
    public $author;
}

$server = new SoapServer("books.wsdl", array('classmap' => array('book' => "MyBook")));
